INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist es wahr, dass eine höhere Abtastfrequenz immer die Signalqualität verbessert?', 2, '[{"text": "Nein", "correct": true, "because": "Abhängig von Signal und Speicherbedarf"}, {"text": "Ja", "correct": false, "because": "Kann unnötige Daten erzeugen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Theorem gibt die minimale Abtastfrequenz für ein Signal an?', 3, '[{"text": "Nyquist-Shannon-Theorem", "correct": true, "because": "Fordert doppelte Signalbandbreite"}, {"text": "Fourier-Theorem", "correct": false, "because": "Für Spektralanalyse"}, {"text": "Shannon-Entropie", "correct": false, "because": "Für Informationstheorie"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren bestimmen die Wahl der Abtastfrequenz?', 5, '[{"text": "Signalbandbreite", "correct": true, "because": "Setzt Mindestanforderung"}, {"text": "Anwendungszweck", "correct": true, "because": "Bestimmt Qualität"}, {"text": "Signalamplitude", "correct": false, "because": "Irrelevant für Frequenz"}, {"text": "Farbtiefe", "correct": false, "because": "Nur bei Bildern"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Eine zu niedrige Frequenz verursacht Aliasing. b) Aliasing verbessert die Rekonstruktion.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, Aliasing verschlechtert"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Festlegung der Abtastfrequenz?', 4, '[{"text": "Signalbandbreite", "correct": false, "because": "Definiert Mindestrate"}, {"text": "Speicherbedarf", "correct": false, "because": "Beeinflusst Machbarkeit"}, {"text": "Signallautstärke", "correct": true, "because": "Kein Frequenzfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob 48 kHz für professionelles Audio üblich ist?', 2, '[{"text": "Ja", "correct": true, "because": "Standard in Studios"}, {"text": "Nein", "correct": false, "because": "48 kHz ist verbreitet"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Maßnahme verhindert Verzerrungen durch zu niedrige Abtastung?', 4, '[{"text": "Tiefpassfilter", "correct": true, "because": "Schneidet hohe Frequenzen"}, {"text": "Hochpassfilter", "correct": false, "because": "Lässt hohe Frequenzen durch"}, {"text": "Datenkompression", "correct": false, "because": "Beeinflusst Datenmenge"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass eine hohe Abtastfrequenz immer Speicher spart. Stimmt das?', 3, '[{"text": "Nein", "correct": true, "because": "Erhöht Speicherbedarf"}, {"text": "Ja", "correct": false, "because": "Mehr Daten pro Sekunde"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist 44,1 kHz nur für Musik relevant?', 2, '[{"text": "Nein", "correct": true, "because": "Auch für Sprache, Sound"}, {"text": "Ja", "correct": false, "because": "Breitere Anwendung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Abtastfrequenzen sind für menschliche Sprache ausreichend?', 5, '[{"text": "8 kHz", "correct": true, "because": "Deckt Sprachbandbreite ab"}, {"text": "16 kHz", "correct": true, "because": "Bietet mehr Klarheit"}, {"text": "96 kHz", "correct": false, "because": "Überdimensioniert"}, {"text": "192 kHz", "correct": false, "because": "Für High-End-Audio"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der Abtastung eines Videosignals?', 4, '[{"text": "Hohe Frequenz für Details", "correct": true, "because": "Sichert Bildqualität"}, {"text": "Niedrige Frequenz", "correct": false, "because": "Verursacht Artefakte"}, {"text": "Signalstärke", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) 96 kHz wird für High-End-Audio genutzt. b) Es ist für Sprache nötig.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, Sprache braucht weniger"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht, um die Abtastfrequenz festzulegen?', 3, '[{"text": "Signalbandbreite", "correct": false, "because": "Setzt Mindestrate"}, {"text": "Anwendung", "correct": false, "because": "Bestimmt Anforderung"}, {"text": "Diagrammfarben", "correct": true, "because": "Kein technischer Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, wie ich die Mindestfrequenz für ein Signal finde?', 4, '[{"text": "Doppelte Signalbandbreite wählen", "correct": true, "because": "Nyquist-Anforderung"}, {"text": "Signalamplitude messen", "correct": false, "because": "Irrelevant"}, {"text": "Zufällige Rate", "correct": false, "because": "Ungenau"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass eine Abtastfrequenz von 192 kHz für alle Anwendungen nötig ist. Stimmt das?', 3, '[{"text": "Nein", "correct": true, "because": "Nur für High-End-Audio"}, {"text": "Ja", "correct": false, "because": "Oft überdimensioniert"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Problem tritt bei zu niedriger Abtastfrequenz auf?', 4, '[{"text": "Aliasing", "correct": true, "because": "Verursacht Frequenzverzerrung"}, {"text": "Datenkompression", "correct": false, "because": "Anderer Prozess"}, {"text": "Signalrauschen", "correct": false, "because": "Unabhängig"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist eine Abtastfrequenz von 16 kHz für Musik ausreichend?', 2, '[{"text": "Nein", "correct": true, "because": "Musik braucht meist 44,1 kHz"}, {"text": "Ja", "correct": false, "because": "Zu niedrig für Qualität"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet eine höhere Abtastfrequenz?', 5, '[{"text": "Bessere Detailtreue", "correct": true, "because": "Mehr Abtastpunkte"}, {"text": "Geringeres Aliasing", "correct": true, "because": "Überschreitet Nyquist"}, {"text": "Weniger Speicherbedarf", "correct": false, "because": "Erhöht Bedarf"}, {"text": "Schnellere Verarbeitung", "correct": false, "because": "Mehr Daten"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei der Wahl einer Abtastfrequenz unwichtig?', 3, '[{"text": "Signalbandbreite", "correct": false, "because": "Definiert Mindestrate"}, {"text": "Qualitätsanforderung", "correct": false, "because": "Bestimmt Frequenz"}, {"text": "Signalvisualisierung", "correct": true, "because": "Nur Darstellung"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie gehe ich vor, wenn ich die Abtastfrequenz für Sprache bestimme?', 4, '[{"text": "8-16 kHz wählen mit Tiefpassfilter", "correct": true, "because": "Sichert Klarheit"}, {"text": "192 kHz nutzen", "correct": false, "because": "Überdimensioniert"}, {"text": "Ohne Filter abtasten", "correct": false, "because": "Risiko für Verzerrung"}]');
